// Transform OpenAI usage data for DuckDB insert
const openaiData = $('Get OpenAI Usage').item.json;
const o365Data = $('Get O365 Licenses').item.json;

const today = new Date().toISOString().split('T')[0];
const monthStart = today.substring(0, 7) + '-01';

// Build usage tracking records
const records = [];

// OpenAI ChatGPT usage
if (openaiData && openaiData.data) {
  records.push({
    license_id: 'LIC-001',
    month: monthStart,
    active_users: openaiData.data.active_users || 0,
    total_queries: openaiData.data.total_requests || 0,
    credit_consumed: openaiData.data.total_cost || 0,
    credit_limit: 180000,
    department: 'All Departments',
    source: 'openai_admin_api'
  });
}

// O365/Copilot license counts
if (o365Data && o365Data.value) {
  for (const sku of o365Data.value) {
    if (sku.skuPartNumber && sku.skuPartNumber.includes('COPILOT')) {
      records.push({
        license_id: 'LIC-003',
        total_seats: sku.prepaidUnits?.enabled || 0,
        assigned_seats: sku.consumedUnits || 0,
        active_seats: sku.consumedUnits || 0,
        source: 'ms_graph_api'
      });
    }
  }
}

return records.map(r => ({ json: r }));
